import zipfile,xml.etree.ElementTree as E
from pathlib import Path
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for p in sorted(Path('docs/liitteet').glob('*.xlsx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  strings=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   strings=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml'))]
  for n in z.namelist():
   if n=='xl/workbook.xml': print(z.read(n).decode())
   if n.startswith('xl/worksheets/sheet') and n.endswith('.xml'):
    print(n)
    t=E.fromstring(z.read(n))
    for row in t.findall('.//s:row',ns):
     cells=[]
     for c in row.findall('s:c',ns):
      v=c.find('s:v',ns)
      val=v.text if v is not None else ''.join(c.itertext())
      if c.get('t')=='s': val=strings[int(val)]
      cells.append(c.get('r')+'='+val)
     print(' | '.join(cells))
PY"

